  const int q = 1, QQ = 2, qb = 3, QQb = 4, g = 5;
  int r_data[] = {q, qb};
  FArray1D<int> r(r_data, 2);
  int RR_data[] = {QQ, QQb};
  FArray1D<int> RR(RR_data, 2);

  std::complex<double> pa;

  for (int hq = 1; hq <= 2; ++hq) {
    for (int hQQ = 1; hQQ <= 2; ++hQQ) {
      pa = std::pow(za(r(hq), RR(hQQ)), 2) / (za(q, qb) * za(QQ, QQb));
